message.content:
{
  "atoms": [
    {
      "entity_scope": "donor",
      "id": "a1",
      "proposition": "the donor has paid at least as much in Income Tax or Capital Gains Tax in the tax year of the donation as the amount of Gift Aid claimed",
      "source_ids": ["E04", "E07"]
    },
    {
      "entity_scope": "donor",
      "id": "a2",
      "proposition": "the donor has made a valid Gift Aid declaration that gives the charity permission to claim Gift Aid",
      "source_ids": ["E05"]
    },
    {
      "entity_scope": "donation",
      "id": "a3",
      "proposition": "the donation is not made through Payroll Giving",
      "source_ids": ["E09"]
    },
    {
      "entity_scope": "donation",
      "id": "a4",
      "proposition": "the donation is not a payment for goods or services or made because the charity bought goods and services",
      "source_ids": ["E10"]
    },
    {
      "entity_scope": "donation",
      "id": "a5",
      "proposition": "the donation does not provide the donor with a benefit that exceeds a certain limit",
      "source_ids": ["E11"]
    },
    {
      "entity_scope": "donation",
      "id": "a6",
      "proposition": "the donation is not shares",
      "source_ids": ["E12"]
    },
    {
      "entity_scope": "donation",
      "id": "a7",
      "proposition": "the donation is not from a charity card or vouchers such as Charities Aid Foundation (CAF) vouchers",
      "source_ids": ["E13"]
    },
    {
      "entity_scope": "charity",
      "id": "a8",
      "proposition": "the charity is recognised as a charity or CASC for tax purposes",
      "source_ids": ["E02"]
    }
  ],
  "decision_target": "eligibility for Gift Aid",
  "decision_unit": "one donation",
  "eligibility_expression": {
    "ref": "a1"
  },
  "limitations": [
    "The tax year of the donation is not established; the donor's tax document covers a prior year and no current-year tax evidence is available.",
    "The Gift Aid declaration is incomplete; the page stating its coverage and duration is missing.",
    "The policy does not specify whether a donation made for an emergency appeal qualifies as a benefit or a service payment, or whether it falls under the 'benefit' exception."
  ],
  "scope_issues": [
    "The policy applies to individual donations, but does not specify whether one-off donations or recurring donations are treated differently in eligibility."
  ]
}
